{
  "src/run.ts": "import { existsSync } from "node:fs";
import { join, resolve } from "node:path";

import type { Models } from "@earendil-works/pi-ai/models";
import type { Extension } from "@earendil-works/pi-durable";

import { Activity, formatStats, oneLine } from "./activity.ts";
import {
	buildPrompt,
	formatFollowUp,
	type PIContext,
	withReplyReminder,
} from "./context.ts";
import { ThreadConversation, type ThreadResult } from "./conversation.ts";
import { createDurableExtensions } from "./durable-extensions.ts";
import { loadExtensions } from "./extensions.ts";
import {
	formatErrorComment,
	formatSuccessComment,
	formatThreadLog,
	formatThreadSummary,
} from "./formatting.ts";
import { createGitHubUi, type GitHubUi } from "./github-ui.ts";
import {
	type GitHubClient,
	isForkPullRequest,
	type ReactionTarget,
} from "./github.ts";
import type { ActionInputs } from "./inputs.ts";
import { createActionModels, findModel } from "./models.ts";
import {
	expandTrigger,
	loadPromptTemplates,
	type PromptSource,
	type PromptTemplates,
} from "./prompts.ts";
import { getRunContext } from "./run-context.ts";
import { GitSyncConflictError } from "./storage/sync.ts";
import type { SnapshotLimits } from "./storage/worktree.ts";
import { Thread } from "./thread.ts";
import { toolEnv } from "./tool-env.ts";
import { collectTriggers, type Trigger, triggerFromInfo } from "./triggers.ts";
import type { Log, TriggerInfo } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type Env = Record<string, string | undefined>;

export interface Logger extends Log {
	debug: (msg: string) => void;
	error: (msg: string) => void;
	setFailed: (msg: string) => void;
	setOutput: (name: string, value: string) => void;
	startGroup: (name: string) => void;
	endGroup: () => void;
}

export interface ActionDependencies {
	inputs: ActionInputs;
	/** The webhook payload of the event that started the workflow. */
	payload: Record<string, unknown>;
	createClient: (token: string) => GitHubClient;
	log: Logger;
	cwd: string;
	/** Override model setup (tests use a faux provider). */
	createModels?: ((inputs: ActionInputs) => Promise<Models>) | undefined;
	/** Git remote holding the thread refs. Default "origin". */
	remote?: string;
	env?: Env;
	/** Appends Markdown to the job summary (notifications from pi-durable extensions). */
	summary?: (markdown: string) => Promise<void>;
}

/**
 * The prompt templates of the run: the extensions' `pi.prompts`, then the project's `.pi/prompts` (with
 * `trust_project` only: anyone who can push a branch can change them), then `<agent_dir>/prompts`.
 */
function promptTemplates(
	deps: ActionDependencies,
	packages: readonly PromptSource[],
): PromptTemplates {
	const { inputs, log, cwd } = deps;
	const project = join(cwd, ".pi", "prompts");
	if (!inputs.trustProject && existsSync(project)) {
		log.info(
			"Not loading the prompt templates in .pi/prompts: trust_project is off",
		);
	}
	const templates = loadPromptTemplates(
		[
			...packages,
			...(inputs.trustProject
				? [{ source: ".pi/prompts", paths: [project] }]
				: []),
			...(inputs.agentDir
				? [
						{
							source: "agent_dir",
							paths: [join(resolve(cwd, inputs.agentDir), "prompts")],
						},
					]
				: []),
		],
		log,
	);
	if (templates.size > 0) {
		log.info(
			`Prompt templates: ${[...templates.values()].map((t) => `/${t.name} (${t.source})`).join(", ")}`,
		);
	}
	return templates;
}

/**
 * The `extensions` input and the model setup: the built-in and custom providers and those extensions register
 * (unless `createModels` overrides it), the pi-durable extensions for the thread, which get the GitHub UI when
 * the run posts to an issue or PR, and the variables the agent's tools get (see `toolEnv()`). pi-durable extensions
 * run in this process, so when there are any, those variables are set in its environment too (after npm ran).
 */
async function setUp(
	deps: ActionDependencies,
	gh: GitHubClient,
	issueNumber: number | undefined,
): Promise<{
	models: Models;
	extensions: Extension[];
	tools: Record<string, string>;
	ui: GitHubUi | undefined;
	templates: PromptTemplates;
}> {
	const { inputs, log, cwd } = deps;
	const env = deps.env ?? process.env;
	const loaded = await loadExtensions({
		specs: inputs.extensions,
		cwd,
		log,
		env,
	});
	const models = deps.createModels
		? await deps.createModels(inputs)
		: await createActionModels(inputs, {
				providers: loaded.providers,
				env,
				log,
			});
	const tools = await toolEnv({ token: inputs.githubToken, cwd, env });
	if (Object.keys(tools).length > 0) {
		log.info(`The agent's tools get ${Object.keys(tools).join(", ")}`);
	}
	if (loaded.durable.length > 0) {
		Object.assign(env, tools);
	}
	const ui =
		inputs.outputMode === "comment" && issueNumber !== undefined
			? createGitHubUi({ gh, issueNumber, log, summary: deps.summary })
			: undefined;
	const extensions = await createDurableExtensions(loaded.durable, {
		cwd,
		agentDir: inputs.agentDir,
		trustProject: inputs.trustProject,
		ui,
		log,
		env,
	});
	return {
		models,
		extensions,
		tools,
		ui,
		templates: promptTemplates(deps, loaded.prompts),
	};
}

/** On cancellation (SIGINT, then SIGTERM), push what the thread has so far before the runner kills us. */
function pushOnSignals(thread: Thread, log: Log): () => void {
	const handler = (signal: NodeJS.Signals) => {
		log.warning(`Received ${signal}; saving the thread before exiting`);
		thread
			.push()
			.catch((error: unknown) => {
				log.warning(getErrorMessage(error));
			})
			.finally(() => {
				process.exitCode = 1;
				process.kill(process.pid, "SIGKILL");
			})
			.catch(() => undefined);
	};
	process.once("SIGINT", handler);
	process.once("SIGTERM", handler);
	return () => {
		process.off("SIGINT", handler);
		process.off("SIGTERM", handler);
	};
}

/** One line for the model, the tools it gets, and the pi-durable extensions, after the setup group. */
function describeSetup(
	inputs: ActionInputs,
	extensions: readonly Extension[],
	modelTools: readonly string[],
): string {
	const loaded = extensions.map(
		(extension) =>
			`${extension.name} (${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"})`,
	);
	return `🤖 ${inputs.provider}/${inputs.model} · tools: ${modelTools.join(", ")}${loaded.length > 0 ? ` · extensions: ${loaded.join(", ")}` : ""}`;
}

/** One line for a request as pi gets it: who, where, and its first line (as typed, for a prompt template). */
function describeTrigger(trigger: Trigger): string {
	const what = trigger.answer ? "Answer" : "Request";
	const where = trigger.url ? ` (${trigger.url})` : "";
	const { template } = trigger;
	const request = template
		? `${oneLine(template.typed)} (prompt template from ${template.source})`
		: oneLine(trigger.task || trigger.text);
	return `▶ ${what} from @${trigger.author.login}${where}: ${request}`;
}

/** The context of the first message of a thread, for the trigger that starts it. */
function contextFor(piContext: PIContext, trigger: Trigger): PIContext {
	return piContext.type === "direct"
		? { ...piContext, task: trigger.task }
		: { ...piContext, task: trigger.task, triggerComment: trigger.text };
}

/** A run from workflow_dispatch or a direct prompt: one request, keyed by the workflow run. */
function oneOffTrigger(piContext: PIContext, env: Env): Trigger {
	const runId = env["GITHUB_RUN_ID"] ?? String(Date.now());
	const attempt = env["GITHUB_RUN_ATTEMPT"] ?? "1";
	return {
		key: `run-${runId}-${attempt}`,
		source: "body",
		issueNumber: piContext.type === "direct" ? 0 : piContext.number,
		author: { login: env["GITHUB_ACTOR"] ?? "workflow", type: "User" },
		text: piContext.task,
		task: piContext.task,
		createdAt: new Date().toISOString(),
	};
}

/** What the run starts with: every unanswered trigger on the thread in comment mode, else one request. */
async function initialTriggers(
	deps: ActionDependencies,
	gh: GitHubClient,
	piContext: PIContext,
	triggerInfo: TriggerInfo | undefined,
	since: Date | undefined,
	answer: Trigger | undefined,
): Promise<Trigger[]> {
	const { inputs } = deps;
	if (!triggerInfo) {
		return [oneOffTrigger(piContext, deps.env ?? process.env)];
	}
	const current = answer ?? triggerFromInfo(triggerInfo, inputs.triggerPhrase);
	return inputs.outputMode === "comment"
		? collectTriggers(gh, triggerInfo, inputs, since, current)
		: [current];
}

/** The working-tree snapshot limits of the thread; undefined (off) by input and on fork pull requests. */
function worktreeLimits(deps: ActionDependencies): SnapshotLimits | undefined {
	const { inputs, log } = deps;
	if (!inputs.worktreeSnapshots) {
		return undefined;
	}
	if (isForkPullRequest(deps.payload)) {
		log.info(
			"A pull request from a fork: its token can't push, so the working tree is not saved",
		);
		return undefined;
	}
	return inputs.worktreeLimits;
}

/** Close the thread, pushing it; a failure to save is a warning, not a failed run. */
async function closeThread(thread: Thread, log: Log): Promise<void> {
	try {
		await thread.close();
	} catch (error) {
		log.warning(
			error instanceof GitSyncConflictError
				? `${thread.ref} moved on the remote while this run worked; its history was not pushed. ${getErrorMessage(error)}`
				: `Could not save the thread: ${getErrorMessage(error)}`,
		);
	}
}

/** The thread, first thing in the log: whether it is new, with how to read it with git in its group. */
function announceThread(deps: ActionDependencies, thread: Thread): void {
	const { log } = deps;
	if (thread.ref === undefined) {
		log.info("🧵 One-off conversation (not stored)");
		return;
	}
	const since = thread.startedAt
		?.toISOString()
		.replace(/:\d\d\.\d+Z$/u, " UTC");
	log.startGroup(
		`🧵 Thread ${thread.ref}: ${since === undefined ? "new" : `continuing, started ${since.replace("T", " ")}`}`,
	);
	log.info(formatThreadLog(thread.ref, deps.remote ?? "origin"));
	log.endGroup();
}

/** After the final push: where the thread is now, in the log, and how to read it, in the job summary. */
async function showThread(
	deps: ActionDependencies,
	thread: Thread,
	ref: string,
): Promise<void> {
	const { log } = deps;
	const remote = deps.remote ?? "origin";
	const { tip } = thread;
	log.info(
		`🧵 ${ref} is at ${tip === undefined ? "(nothing stored)" : tip.slice(0, 7)}`,
	);
	try {
		await deps.summary?.(formatThreadSummary(ref, remote));
	} catch (error) {
		log.warning(`Could not write the job summary: ${getErrorMessage(error)}`);
	}
}

export async function run(deps: ActionDependencies): Promise<void> {
	const resolved = await getRunContext(deps);
	if (!resolved) {
		return;
	}
	const { piContext, ghClient: gh, triggerInfo } = resolved;
	const { inputs, log } = deps;
	const activity = new Activity(log);
	const issueNumber =
		piContext.type === "direct" ? undefined : piContext.number;
	// In comment mode, a trigger makes the run a conversation on its issue or PR (reactions, new comments join).
	const interactive = inputs.outputMode === "comment" ? triggerInfo : undefined;

	/** Set the outputs, or react on `target` and post the result unless it was posted before. Returns where it went. */
	const report = async (
		result: ThreadResult,
		target: ReactionTarget | undefined,
		ref?: string,
		alreadyPosted = false,
	): Promise<string | undefined> => {
		if (!result.success) {
			log.error(`pi execution failed: ${result.error}`);
		}
		const stats = formatStats(activity.take());
		if (inputs.outputMode === "output") {
			log.info(`${result.success ? "✅" : "❌"} Set the outputs (${stats})`);
			log.setOutput("success", String(result.success));
			log.setOutput(
				"response",
				result.success ? result.response : result.error,
			);
			return "output";
		}
		if (target) {
			await gh.addReaction(target, result.success ? "rocket" : "confused");
		}
		if (alreadyPosted || issueNumber === undefined) {
			return undefined;
		}
		const body = result.success
			? formatSuccessComment(result.response, ref)
			: formatErrorComment(result.error, ref);
		const { url } = await gh.createComment(issueNumber, body);
		log.info(
			`${result.success ? "✅ Replied" : "❌ Reported the error"}: ${url} (${stats})`,
		);
		return url;
	};

	if (interactive) {
		await gh.addReaction(interactive, "eyes");
	}
	let thread: Thread | undefined;
	let stopSignals: (() => void) | undefined;
	try {
		log.startGroup("Setup");
		let setup: Awaited<ReturnType<typeof setUp>>;
		try {
			setup = await setUp(deps, gh, issueNumber);
		} finally {
			log.endGroup();
		}
		const { models, extensions, tools, ui, templates } = setup;
		const expand = (triggers: Trigger[]) =>
			triggers.map((trigger) => expandTrigger(trigger, templates));
		const opened = await Thread.open({
			cwd: deps.cwd,
			issueNumber,
			models,
			model: findModel(models, inputs.provider, inputs.model),
			log,
			remote: deps.remote,
			extensions,
			tools: { exclude: inputs.excludeTools, hidden: inputs.modelToolsHidden },
			toolEnv: tools,
			worktree: worktreeLimits(deps),
			onEntries: (entries) => {
				activity.entries(entries);
			},
		});
		thread = opened;
		log.info(describeSetup(inputs, extensions, opened.modelTools));
		stopSignals = pushOnSignals(opened, log);
		announceThread(deps, opened);
		// New comments: on a new thread, from the time of the trigger; on an existing one, since it began.
		const since =
			opened.startedAt ??
			new Date(
				Date.parse(interactive?.createdAt ?? new Date().toISOString()) - 1000,
			);
		const conversation = new ThreadConversation({
			thread: opened,
			log,
			timeoutSeconds: inputs.timeout,
			pollIntervalMs: inputs.pollInterval * 1000,
			message: async (trigger, first) => {
				// As `report` does, pi-action posts the reply: say so, or pi may post it with `gh` too (#42).
				const repliesAsComment =
					inputs.outputMode === "comment" && issueNumber !== undefined;
				if (first && !trigger.answer) {
					return buildPrompt(
						contextFor(piContext, trigger),
						inputs.promptTemplate,
						{ repliesAsComment },
					);
				}
				const message = trigger.answer ? trigger.text : formatFollowUp(trigger);
				return repliesAsComment ? withReplyReminder(message) : message;
			},
			started: (trigger) => {
				log.info(describeTrigger(trigger));
			},
			deliver: async (trigger, result, alreadyPosted) =>
				report(
					result,
					interactive ? trigger : undefined,
					opened.ref,
					alreadyPosted,
				),
			...(interactive
				? {
						poll: async () =>
							expand(await collectTriggers(gh, interactive, inputs, since)),
					}
				: {}),
			...(ui ? { asked: () => ui.asked } : {}),
		});
		await conversation.run(
			expand(
				await initialTriggers(
					deps,
					gh,
					piContext,
					triggerInfo,
					opened.startedAt,
					resolved.answer,
				),
			),
		);
		if (conversation.failures.length > 0) {
			log.setFailed(
				`pi could not answer ${conversation.failures.length} comment(s): ${conversation.failures.join("; ")}`,
			);
		}
	} catch (error) {
		await report(
			{ success: false, error: getErrorMessage(error) },
			interactive,
		);
	} finally {
		stopSignals?.();
		if (thread) {
			await closeThread(thread, log);
			if (thread.ref !== undefined) {
				await showThread(deps, thread, thread.ref);
			}
		}
	}
}
",
  "src/thread.ts": "import {
	BACKGROUND_CONTEXT,
	type Context,
} from "@earendil-works/chord/context";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { Models } from "@earendil-works/pi-ai/models";
import {
	type AgentChange,
	AssistantEntry,
	type CommitResult,
	type Conversation,
	createRegistry,
	type EntryId,
	type EntryRecord,
	type Extension,
	Harness,
	MemoryStorage,
	type Storage,
	type StorageWrite,
	type Submission,
	type ToolRegistration,
	ToolResultEntry,
} from "@earendil-works/pi-durable";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import { GitStorage } from "./storage/git-storage.ts";
import { git } from "./storage/git.ts";
import { GitSync, isTurnBoundary, liveRef } from "./storage/sync.ts";
import { type SnapshotLimits, worktreeRef } from "./storage/worktree.ts";
import { planTools, type ToolSelection } from "./tool-filter.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";
import { RESTORE_ENTRY_KIND, WorktreeContinuity } from "./worktree.ts";

const context: Context = BACKGROUND_CONTEXT;

const POSTED_KIND = "pi-action.posted";
const COMMENT_KIND = "pi-action.comment";
const KEY_FIELD = "key";
const URL_FIELD = "url";

export const threadRef = (issueNumber: number): string =>
	`refs/pi/threads/${issueNumber}`;

export interface ThreadOptions {
	cwd: string;
	/** The issue or PR; undefined for a one-off prompt, which is kept in memory only. */
	issueNumber?: number | undefined;
	models: Models;
	model: Model<Api>;
	log: Log;
	remote?: string | undefined;
	/** pi-durable extensions from the `extensions` input, installed after the coding tools. */
	extensions?: readonly Extension[];
	/** The `exclude_tools` and `model_tools_hidden` inputs; none when undefined. */
	tools?: ToolSelection | undefined;
	/** Variables the tools' shell gets on top of the process environment (see `toolEnv()`). */
	toolEnv?: Readonly<Record<string, string>> | undefined;
	/** Save and restore the working tree with the thread (stored threads only), with these limits; undefined: don't. */
	worktree?: SnapshotLimits | undefined;
	/** Called with the entries of each stored commit, in order (see activity.ts); must not throw. */
	onEntries?: ((entries: readonly EntryRecord[]) => void) | undefined;
}

/** The entries among `writes`. */
function entriesOf(writes: readonly StorageWrite[]): EntryRecord[] {
	return writes.flatMap((write) =>
		write.type === "entry" ? [write.value] : [],
	);
}

/** A one-off conversation's storage, which reports the entries it stores as GitStorage's `onCommit` does. */
class ObservedMemoryStorage extends MemoryStorage {
	private readonly onEntries: (entries: readonly EntryRecord[]) => void;

	constructor(onEntries: (entries: readonly EntryRecord[]) => void) {
		super();
		this.onEntries = onEntries;
	}

	override async commit(
		...args: Parameters<MemoryStorage["commit"]>
	): Promise<CommitResult> {
		const result = await super.commit(...args);
		this.onEntries(
			args[0].slice(0, result.stored).flatMap((writes) => entriesOf(writes)),
		);
		return result;
	}
}

/** What `Thread.answerText()` reports about a run's answer. */
export interface RunAnswer {
	text: string;
	toolCalls: boolean;
	/** The assistant message's stop reason; `length` when it hit the output token limit (max_tokens). */
	stopReason: string | undefined;
	/** Whether the run executed tools before this answer. */
	usedTools: boolean;
}

export interface ThreadInput {
	/** Stable per GitHub item, e.g. `comment-123`: resubmitting it returns the same submission. */
	key: string;
	content: string;
	data: Record<string, string>;
	/** Place the input as this entry instead of a comment (an answer to a question: `ui.answer`). */
	entry?: { kind: string; data: Record<string, string | boolean> } | undefined;
}

interface Persistence {
	ref: string;
	storage: GitStorage;
	saver: ThreadSaver;
	worktree: WorktreeContinuity | undefined;
	startedAt: Date | undefined;
	isNew: boolean;
}

/** The local tip of `ref`, undefined when it doesn't exist. */
async function localTip(cwd: string, ref: string): Promise<string | undefined> {
	const out = await git(cwd, ["rev-parse", "-q", "--verify", ref]).catch(
		() => "",
	);
	return out.trim() || undefined;
}

/** Pushes the thread, and the working-tree snapshots with it. */
class ThreadSaver {
	private readonly cwd: string;
	private readonly sync: GitSync;
	private readonly worktree: WorktreeContinuity | undefined;
	/** Set once the storage is open. */
	storage: GitStorage | undefined;

	constructor(
		cwd: string,
		sync: GitSync,
		worktree: WorktreeContinuity | undefined,
	) {
		this.cwd = cwd;
		this.sync = sync;
		this.worktree = worktree;
	}

	/** Push now (`flush`) or soon (`schedule`), saving the working tree first when `save`. */
	async push(how: "schedule" | "flush", save: boolean): Promise<void> {
		const tip = () => this.storage?.tip;
		if (this.worktree !== undefined && save) {
			await this.worktree.checkpoint();
		}
		const companion =
			this.worktree === undefined
				? undefined
				: await localTip(this.cwd, this.worktree.ref);
		const current = tip();
		if (how === "flush") {
			await this.sync.flush(current, companion);
		} else if (current !== undefined) {
			await this.sync.schedule(current, companion);
		}
	}
}

async function openPersistence(
	options: ThreadOptions,
	issueNumber: number,
): Promise<Persistence> {
	const { cwd, log } = options;
	const ref = threadRef(issueNumber);
	// The run works on local refs outside refs/pi/, where a fetch the agent runs can't move them (#46).
	const local = liveRef(ref);
	const worktree =
		options.worktree === undefined
			? undefined
			: new WorktreeContinuity({
					cwd,
					ref: liveRef(worktreeRef(issueNumber)),
					name: worktreeRef(issueNumber),
					limits: options.worktree,
					log,
					remote: options.remote,
				});
	const sync = new GitSync({
		repo: cwd,
		ref,
		localRef: local,
		companionRef: worktree === undefined ? undefined : worktreeRef(issueNumber),
		localCompanionRef: worktree?.ref,
		log: log.debug ?? log.info,
		remote: options.remote,
	});
	const remoteTip = await sync.fetch();
	const saver = new ThreadSaver(cwd, sync, worktree);
	const storage = await GitStorage.open({
		repo: cwd,
		ref: local,
		author: {
			name: "pi-action",
			email: "pi-action@users.noreply.github.com",
		},
		onCommit: ({ batches }) => {
			options.onEntries?.(batches.flatMap((batch) => entriesOf(batch.writes)));
			if (isTurnBoundary(batches)) {
				saver.push("schedule", true).catch((error: unknown) => {
					log.warning(getErrorMessage(error));
				});
			}
		},
	});
	saver.storage = storage;
	return {
		ref,
		storage,
		saver,
		worktree,
		isNew: remoteTip === undefined,
		startedAt: remoteTip ? await rootCommitTime(cwd, local) : undefined,
	};
}

/**
 * One GitHub issue or PR as a durable pi conversation, stored in git on refs/pi/threads/<n> and pushed to the
 * remote at every turn boundary. Without an issue number, the conversation lives in memory for this run only.
 */
export class Thread {
	private closed = false;
	private readonly harness: Harness;
	private readonly root: Conversation;
	private readonly persistence: Persistence | undefined;
	/** The names of the tools the model is offered. */
	readonly modelTools: readonly string[];

	private constructor(
		harness: Harness,
		root: Conversation,
		persistence: Persistence | undefined,
		modelTools: readonly string[],
	) {
		this.harness = harness;
		this.root = root;
		this.persistence = persistence;
		this.modelTools = modelTools;
	}

	static async open(options: ThreadOptions): Promise<Thread> {
		const { cwd } = options;
		const persistence =
			options.issueNumber === undefined
				? undefined
				: await openPersistence(options, options.issueNumber);
		const { onEntries } = options;
		const storage: Storage =
			persistence?.storage ??
			(onEntries === undefined
				? new MemoryStorage()
				: new ObservedMemoryStorage(onEntries));
		const registry = createRegistry();
		registry.install(CodingTools);
		for (const extension of options.extensions ?? []) {
			registry.install(extension);
		}
		const harness = await Harness.open(
			storage,
			{
				models: options.models,
				registry,
				env: ({ cwd: dir }) =>
					new NodeExecutionEnv({
						cwd: dir ?? cwd,
						shellEnv: { ...options.toolEnv },
					}),
				settings: { retry: { maxRetries: 2 } },
			},
			context,
		);
		const agent = {
			model: { provider: options.model.provider, modelId: options.model.id },
			cwd,
		};
		let modelTools: string[];
		let root: Conversation;
		try {
			root = await harness.root(context, { agent });
			modelTools = await configureAgent(root, agent, options);
		} catch (error) {
			await harness.close(context);
			throw error;
		}
		await restoreWorktree(persistence?.worktree, harness, root);
		harness.resume(); // finish whatever a previous, interrupted run left
		return new Thread(harness, root, persistence, modelTools);
	}

	/** The commit the thread's ref points at, undefined before its first commit or when it is not stored. */
	get tip(): string | undefined {
		return this.persistence?.storage.tip;
	}

	/** The thread's ref, when it is stored in git. */
	get ref(): string | undefined {
		return this.persistence?.ref;
	}

	/** A thread nothing was stored for yet (always, in memory). */
	get isNew(): boolean {
		return this.persistence?.isNew ?? true;
	}

	/** When the thread's first commit was made; undefined for a new thread. */
	get startedAt(): Date | undefined {
		return this.persistence?.startedAt;
	}

	/** Comments arriving while a run works join it (steer); otherwise they start one. */
	async submit(input: ThreadInput): Promise<Submission> {
		return this.root.submit(
			{
				type: "input",
				content: input.content,
				requestId: input.key,
				whenBusy: "steer",
				entry: input.entry ?? {
					kind: COMMENT_KIND,
					data: { key: input.key, ...input.data },
				},
			},
			context,
		);
	}

	/**
	 * A run's answer: its text, whether it called tools (a run that ended on a `terminate` round), and why the
	 * model stopped (`length`: it ran out of output tokens); and whether the run executed any tool between its
	 * `input` entry and the answer.
	 */
	async answerText(answer: EntryId, input: EntryId): Promise<RunAnswer> {
		const entry = await this.root.commit(
			async (tx) => tx.entry(AssistantEntry, answer),
			context,
		);
		const message = entry?.model?.[0];
		const usedTools = await this.ranTools(input, answer);
		if (message?.role !== "assistant") {
			return { text: "", toolCalls: false, stopReason: undefined, usedTools };
		}
		return {
			text: message.content
				.flatMap((block) => (block.type === "text" ? [block.text] : []))
				.join("")
				.trim(),
			toolCalls: message.content.some((block) => block.type === "toolCall"),
			stopReason: message.stopReason,
			usedTools,
		};
	}

	/** Whether a tool result was written between two entries. */
	private async ranTools(from: EntryId, to: EntryId): Promise<boolean> {
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ minEntryId: from, maxEntryId: to, order: "descending" },
				500,
				cursor,
				context,
			);
			if (page.items.some((item) => item.kind === ToolResultEntry.kind)) {
				return true;
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return false;
	}

	/** Results already posted (`answer-<entryId>`, `error-<submissionId>`), with their comment URLs. */
	async postedResults(): Promise<Map<string, string>> {
		const posted = new Map<string, string>();
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ order: "ascending" },
				500,
				cursor,
				context,
			);
			for (const { kind, data } of page.items) {
				if (kind === POSTED_KIND && typeof data === "object" && data !== null) {
					const key: unknown = Reflect.get(data, KEY_FIELD);
					const url: unknown = Reflect.get(data, URL_FIELD);
					if (typeof key === "string") {
						posted.set(key, typeof url === "string" ? url : "");
					}
				}
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return posted;
	}

	async markPosted(key: string, url: string): Promise<void> {
		await this.root.submit(
			{
				type: "write",
				entry: { kind: POSTED_KIND, data: { key, url } },
				requestId: `posted-${key}`,
			},
			context,
		);
	}

	async abort(): Promise<void> {
		await this.root.abort(context);
	}

	/** Push what is committed so far (with the working-tree snapshots); throws if the remote moved under us. */
	async push(): Promise<void> {
		await this.persistence?.saver.push("flush", false);
	}

	async close(): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		const worktree = this.persistence?.worktree;
		await worktree?.checkpoint();
		// Turn boundaries the closing harness still commits must not save into a closed conversation.
		worktree?.detach();
		await this.harness.close(context);
		await this.push();
	}
}

/**
 * Configure the conversation for this run (the model, the tools may differ from the last run's): clear the last run's
 * tool filters, resolve the inputs against the tools there are now, and apply them. Returns the tools the model gets.
 */
async function configureAgent(
	root: Conversation,
	agent: AgentChange,
	options: ThreadOptions,
): Promise<string[]> {
	await root.configure({ ...agent, tools: null, modelTools: null }, context);
	const resolved = await root.agent(context);
	const byName = new Map<string, ToolRegistration>();
	for (const tool of [
		...resolved.tools,
		...resolved.callable,
		...resolved.deferred,
	]) {
		byName.set(tool.name, tool);
	}
	const offered = resolved.tools.map((tool) => tool.name);
	if (options.tools === undefined) {
		return offered;
	}
	const plan = planTools(
		options.tools,
		[...byName.keys()],
		offered,
		options.log,
	);
	const pick = (names: readonly string[]) =>
		names.flatMap((name) => byName.get(name) ?? []);
	if (plan.exclude.length > 0 || plan.hide.length > 0) {
		await root.configure(
			{
				...(plan.exclude.length > 0
					? { tools: { remove: pick(plan.exclude) } }
					: {}),
				...(plan.hide.length > 0
					? { modelTools: { remove: pick(plan.hide) } }
					: {}),
			},
			context,
		);
	}
	return plan.offered;
}

/**
 * Restore the working tree the conversation points at, before any work resumes, and tell the model how it went
 * (one entry with a user message).
 */
async function restoreWorktree(
	worktree: WorktreeContinuity | undefined,
	harness: Harness,
	root: Conversation,
): Promise<void> {
	if (worktree === undefined) {
		return;
	}
	worktree.attach(harness, root);
	const message = await worktree.restore();
	if (message !== undefined) {
		await root.submit(
			{
				type: "write",
				entry: {
					kind: RESTORE_ENTRY_KIND,
					data: { message },
					model: [{ role: "user", content: message, timestamp: Date.now() }],
				},
			},
			context,
		);
	}
}

/** When the thread's root commit was made. */
async function rootCommitTime(
	cwd: string,
	ref: string,
): Promise<Date | undefined> {
	const out = await git(cwd, [
		"log",
		"--max-parents=0",
		"--format=%cI",
		ref,
	]).catch(() => "");
	const [time] = out.trim().split("\n");
	return time ? new Date(time) : undefined;
}
